/* ================= VIEWS: finance, assessment, teacher, parent ================= */

/* ---------- FINANCE OVERVIEW ---------- */
V.finance=()=>{const f=finSeries(),ag=aging();const nov=monthInvoiced("2026-11"),novC=monthCollected("2026-11"),oct=monthInvoiced("2026-10"),octC=monthCollected("2026-10");
  const out=S.invoices.filter(i=>i.status!=="paid").reduce((s,i)=>s+i.amount,0),od=S.invoices.filter(i=>i.status==="overdue");
  const octExp=monthExpenses("2026-10");
  return ph("","Term 1 · 2026–27 · all amounts in OMR",`<button class="btn sm light" onclick="exportFin()">⬇ Export P&L</button><button class="btn sm navy" onclick="go('invoices')">Fees & invoices →</button>`)+`
  <div class="kpis"><div class="kpi"><small>November billed</small><b>${f0(nov)}</b><em>${pct(novC,nov)}% paid early</em></div><div class="kpi"><small>October collected</small><b>${f0(octC)}</b><em class="up">${pct(octC,oct)}% collection rate</em>${spark(f.col.slice(-6,-1),"#14213d")}</div>
   <div class="kpi"><small>Outstanding</small><b>${f0(out)}</b><em class="w">${od.length} overdue invoices</em></div><div class="kpi"><small>October expenses</small><b>${f0(octExp)}</b><em>payroll ${f0(payroll())}</em></div>
   <div class="kpi"><small>October net</small><b>${f0(octC-octExp)}</b><em class="${octC-octExp>0?"up":"dn"}">${pct(octC-octExp,octC)}% margin</em></div><div class="kpi"><small>Paid online by card</small><b>${pct(S.payments.filter(p=>p.method==="Card").length,S.payments.length)}%</b><em>of all payments</em></div></div>
  <div class="g g21"><div class="card"><h3>Monthly collected vs expenses</h3>${chart("bar",{labels:f.labs,series:[{name:"Collected",color:"#14213d",data:f.col},{name:"Invoiced",color:"#13b5d6",data:f.inv},{name:"Expenses",color:"#ef7d6b",data:f.exp.map(v=>v||0)}],unit:" OMR"},250)}<div class="legend"><span><i style="background:#14213d"></i>Collected</span><span><i style="background:#13b5d6"></i>Invoiced</span><span><i style="background:#ef7d6b"></i>Expenses</span></div></div>
   <div class="card"><h3>Payment methods</h3>${chart("donut",{data:methodData(),center:S.payments.length,sub:"payments"},250)}</div></div>
  <div class="g g2" style="margin-top:14px"><div class="card"><h3>Outstanding by age</h3>${chart("hbar",{items:Object.entries(ag).map(([k,v],i)=>({label:k,value:v,color:["#13b5d6","#f7a21e","#ef7d6b","#d64545"][i]})),fmt:f0,unit:" OMR"},170)}</div>
   <div class="card"><h3>Top overdue accounts<span class="x"><button class="btn sm" onclick="remindAll()">Send reminders</button></span></h3>${od.slice(0,5).map(i=>`<div class="row">${kidCell(K(i.kid),esc(K(i.kid).mother)+" · "+monthName(i.month))}<b class="num">${f3(i.amount)}</b></div>`).join("")||'<div class="list-empty">No overdue invoices 🎉</div>'}</div></div>`};
function exportFin(){const f=finSeries();csv("profit-and-loss-2026.csv",[["Month","Invoiced","Collected","Expenses","Net"]].concat(f.labs.map((l,i)=>[l,f.inv[i],f.col[i],f.exp[i]||"",f.exp[i]?f.col[i]-f.exp[i]:""])))}
function remindAll(){const un=S.invoices.filter(i=>i.status!=="paid");const parents=new Set(un.map(i=>K(i.kid).mother));logComm("WhatsApp + SMS",parents.size+" parents","Fee reminder with secure card-payment link");toast(`Reminders with payment link sent to ${parents.size} parents`)}

/* ---------- INVOICES ---------- */
V.invoices=(p)=>{p=p||{};const m=p.m||"2026-11",st=p.st||"",cls=p.cls||"",q=(p.q||"").toLowerCase();
  const list=S.invoices.filter(i=>(m==="all"||i.month===m)&&(!st||i.status===st)&&(!cls||K(i.kid).cls===cls)&&(!q||(K(i.kid).name+K(i.kid).mother+i.no).toLowerCase().includes(q)));
  const tot=list.reduce((s,i)=>s+i.amount,0),paid=list.filter(i=>i.status==="paid").reduce((s,i)=>s+i.amount,0);const P=o=>JSON.stringify(Object.assign({m,st,cls,q:p.q||""},o)).replace(/"/g,"'");
  return `<div class="toolbar"><div class="seg">${[["2026-09","Sep"],["2026-10","Oct"],["2026-11","Nov"],["2026-12","Dec"],["all","All"]].map(x=>`<button class="${m===x[0]?"on":""}" onclick="go('invoices',${P({m:x[0]})})">${x[1]}</button>`).join("")}</div>
   <select onchange="go('invoices',${P({}).slice(0,-1)},st:this.value})"><option value="">Any status</option>${["paid","due","overdue"].map(s=>`<option ${st===s?"selected":""}>${s}</option>`).join("")}</select>
   <select onchange="go('invoices',${P({}).slice(0,-1)},cls:this.value})"><option value="">All classes</option>${S.CLASSES.map(c=>`<option value="${c.id}" ${cls===c.id?"selected":""}>${c.name}</option>`).join("")}</select>
   <input type="search" placeholder="Search…" value="${esc(p.q||"")}" onchange="go('invoices',${P({}).slice(0,-1)},q:this.value})"><span class="sp"></span>
   ${me.role!=="principal"?`<button class="btn sm light" onclick="remindAll()">📲 Remind unpaid</button><button class="btn sm navy" onclick="genInvoices()" ${S.invoices.some(i=>i.month==="2026-12")?"disabled":""}>Generate December</button>`:""}<button class="btn sm light" onclick="exportInv('${m}')">⬇ CSV</button></div>
  <div class="kpis"><div class="kpi"><small>Invoices</small><b>${list.length}</b></div><div class="kpi"><small>Billed</small><b>${f3(tot)}</b><em>OMR</em></div><div class="kpi"><small>Collected</small><b>${f3(paid)}</b><em class="up">${pct(paid,tot)}%</em></div><div class="kpi"><small>Outstanding</small><b>${f3(tot-paid)}</b><em class="w">OMR</em></div></div>
  <div class="card"><div class="tbl"><table><thead><tr><th>Invoice</th><th>Student</th><th>Description</th><th class="r">Amount</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>${list.slice(0,80).map(i=>{const k=K(i.kid);return `<tr><td class="num">${i.no}</td><td>${kidCell(k,C(k.cls).name+(k.discount?` · sibling −${k.discount}%`:""))}</td><td>${esc(i.item)}</td><td class="r num"><b>${f3(i.amount)}</b></td><td>${fd(i.due)}</td><td>${invStatus(i)}</td><td style="white-space:nowrap"><button class="btn sm light" onclick="voucher('${i.no}')">Voucher</button> ${i.status!=="paid"&&me.role!=="principal"?`<button class="btn sm" onclick="recordPay('${i.no}')">Record payment</button>`:""}</td></tr>`}).join("")}</tbody></table>${list.length>80?`<div class="hint" style="padding:8px">Showing 80 of ${list.length}. Use filters to narrow down.</div>`:""}</div></div>`};
function exportInv(m){csv("invoices-"+m+".csv",[["Invoice","Student","Class","Parent","Description","Amount OMR","Issued","Due","Status"]].concat(S.invoices.filter(i=>m==="all"||i.month===m).map(i=>{const k=K(i.kid);return[i.no,k.name,C(k.cls).name,k.mother,i.item,i.amount,i.issued,i.due,i.status]})))}
function genInvoices(){let n=0;S.kids.forEach(k=>{const amt=+(C(k.cls).fee*(1-k.discount/100)).toFixed(3);S.invoices.push({no:"INV-"+(3000+n),kid:k.id,month:"2026-12",item:"Tuition – December",lines:[["Tuition – December",amt]],amount:amt,issued:DEMO_TODAY,due:"2026-12-01",status:"due"});n++});logComm("WhatsApp + Email","All parents ("+n+")","December invoices issued · pay online");toast(`${n} December invoices generated & sent to parents`);go("invoices",{m:"2026-12"})}
function recordPay(no){const i=S.invoices.find(x=>x.no===no),k=K(i.kid);modal(mh("Record payment",i.no+" · "+esc(k.name))+`<div class="sum tot"><span>Amount</span><span>${f3(i.amount)} OMR</span></div><div style="height:10px"></div><div class="f2"><div class="f"><label>Method</label><select id="pm"><option>Cash</option><option>Bank transfer</option><option>Card (POS)</option><option>Cheque</option></select></div><div class="f"><label>Date</label><input id="pd" type="date" value="${DEMO_TODAY}"></div></div><div class="f"><label>Reference / note</label><input id="pr" placeholder="Optional"></div><button class="btn full" onclick="doRecord('${no}')">Save & send receipt</button>`)}
function doRecord(no){const i=S.invoices.find(x=>x.no===no);i.status="paid";const r={no:"RCP-"+(5000+S.payments.length),inv:no,kid:i.kid,amount:i.amount,method:$("#pm").value.replace(" (POS)",""),card:null,date:$("#pd").value,by:me.name};S.payments.unshift(r);logComm("WhatsApp",K(i.kid).mother,"Receipt "+r.no+" for "+f3(i.amount)+" OMR");closeModal();toast("Payment recorded · receipt "+r.no+" sent");go(view,param)}
function voucher(no){const i=S.invoices.find(x=>x.no===no),k=K(i.kid);const lines=i.lines||[[i.item,i.amount]];
  modal(`<div class="printable doc">${docHead("FEE INVOICE",i.no)}<div class="g g2" style="gap:10px;margin-bottom:12px"><div><small style="color:var(--muted)">Billed to</small><br><b>${esc(k.mother)}</b><br>${k.phone}<br>${k.email}</div><div style="text-align:end"><small style="color:var(--muted)">Student</small><br><b>${esc(k.name)}</b> (${k.id})<br>${C(k.cls).name}<br>Issued ${fd(i.issued)} · Due <b>${fd(i.due)}</b></div></div>
  <table><thead><tr><th>Description</th><th class="r">Amount (OMR)</th></tr></thead><tbody>${lines.map(l=>`<tr><td>${esc(l[0])}</td><td class="r num">${f3(l[1])}</td></tr>`).join("")}${k.discount?`<tr><td colspan="2" style="color:var(--muted);font-size:12px">Includes sibling discount of ${k.discount}%</td></tr>`:""}<tr><td><b>Total</b></td><td class="r"><b>${f3(i.amount)}</b></td></tr></tbody></table>
  <div style="display:flex;gap:16px;align-items:center;margin-top:16px;background:var(--bg);border-radius:12px;padding:12px"><div style="transform:scale(.5);transform-origin:left center;width:100px;height:100px">${qrSvg(i.no)}</div><div style="font-size:12px"><b>Pay online by card</b><br>Scan the QR code or open the TwinkleStar Parent Portal → Fees.<br>Bank transfer: Bank Muscat · Account 0xxx-xxxxxx-xxx · Ref ${i.no}</div></div>
  <div style="margin-top:12px">${invStatus(i)}</div><div class="sig"><span>Accounts</span><span>Stamp</span></div></div>
  <div class="noprint" style="display:flex;gap:8px;margin-top:16px"><button class="btn" onclick="printDoc()">🖨 Print / PDF</button><button class="btn light" onclick="closeModal()">Close</button></div>`,"wide")}

/* ---------- PAYMENTS ---------- */
V.payments=(p)=>{p=p||{};const mt=p.mt||"";const list=S.payments.filter(x=>!mt||x.method===mt);const tot=list.reduce((s,x)=>s+x.amount,0);
  return `<div class="toolbar"><div class="seg">${["","Card","Bank transfer","Cash"].map(x=>`<button class="${mt===x?"on":""}" onclick="go('payments',{mt:'${x}'})">${x||"All"}</button>`).join("")}</div><span class="sp"></span><button class="btn sm light" onclick="csv('payments.csv',[['Receipt','Invoice','Student','Method','Card','Date','Amount','Recorded by']].concat(S.payments.map(p=>[p.no,p.inv,K(p.kid).name,p.method,p.card?'**** '+p.card:'',p.date,p.amount,p.by])))">⬇ Export for accounting</button></div>
  <div class="kpis"><div class="kpi"><small>Payments</small><b>${list.length}</b></div><div class="kpi"><small>Total received</small><b>${f3(tot)}</b><em>OMR</em></div><div class="kpi"><small>Via parent portal</small><b>${list.filter(x=>x.by==="Parent portal").length}</b><em class="up">card, 3-D Secure</em></div></div>
  <div class="card"><div class="tbl"><table><thead><tr><th>Receipt</th><th>Date</th><th>Student</th><th>Invoice</th><th>Method</th><th class="r">Amount</th><th></th></tr></thead><tbody>${list.slice(0,80).map(x=>`<tr><td class="num">${x.no}</td><td>${fd(x.date)}</td><td>${kidCell(K(x.kid))}</td><td class="num">${x.inv}</td><td>${x.method}${x.card?` •••• ${x.card}`:""}<small style="display:block;color:var(--muted)">${esc(x.by)}</small></td><td class="r num"><b>${f3(x.amount)}</b></td><td><button class="btn sm light" onclick="receipt('${x.no}')">Receipt</button></td></tr>`).join("")}</tbody></table></div></div>`};
function receipt(no){const r=S.payments.find(x=>x.no===no),k=K(r.kid),i=S.invoices.find(x=>x.no===r.inv);
  modal(`<div class="printable doc">${docHead("PAYMENT RECEIPT",r.no)}<table><tbody><tr><td>Received from</td><td class="r"><b>${esc(k.mother)}</b></td></tr><tr><td>Student</td><td class="r">${esc(k.name)} · ${C(k.cls).name}</td></tr><tr><td>For</td><td class="r">${esc(i?i.item:"")} (${r.inv})</td></tr><tr><td>Method</td><td class="r">${r.method}${r.card?" •••• "+r.card:""}</td></tr><tr><td>Date</td><td class="r">${fd(r.date)}</td></tr><tr><td><b>Amount</b></td><td class="r"><b style="font-size:16px">${f3(r.amount)} OMR</b></td></tr></tbody></table><div style="text-align:center;margin-top:18px"><span class="st ok" style="font-size:13px">✓ PAID</span></div><div class="sig"><span>Accounts</span><span>TwinkleStar</span></div></div>
  <div class="noprint" style="display:flex;gap:8px;margin-top:16px"><button class="btn" onclick="printDoc()">🖨 Print / PDF</button><button class="btn light" onclick="closeModal()">Close</button></div>`)}

/* ---------- EXPENSES & PAYROLL ---------- */
V.expenses=(p)=>{const tab=(p&&p.tab)||"exp";const seg=`<div class="toolbar"><div class="seg"><button class="${tab==="exp"?"on":""}" onclick="go('expenses',{tab:'exp'})">Expenses</button><button class="${tab==="pay"?"on":""}" onclick="go('expenses',{tab:'pay'})">Payroll</button></div><span class="sp"></span>${tab==="exp"?`<button class="btn sm navy" onclick="addExpense()">+ Add expense</button>`:""}</div>`;
  if(tab==="exp"){const cats={};S.expenses.forEach(e=>cats[e[1]]=(cats[e[1]]||0)+e[3]);
    return seg+`<div class="g g12"><div class="card"><h3>October by category</h3>${chart("donut",{data:Object.entries(cats).map(([k,v],i)=>({label:k,value:Math.round(v),color:COL[i%6]})),center:f0(Object.values(cats).reduce((a,b)=>a+b,0)),sub:"OMR excl. payroll",fmt:f0},230)}</div>
     <div class="card"><div class="tbl"><table><thead><tr><th>Date</th><th>Category</th><th>Description</th><th>Paid by</th><th class="r">Amount</th></tr></thead><tbody>${S.expenses.map(e=>`<tr><td>${fd(e[0])}</td><td><span class="st mute">${e[1]}</span></td><td>${esc(e[2])}</td><td>${e[4]}</td><td class="r num"><b>${f3(e[3])}</b></td></tr>`).join("")}</tbody></table></div></div></div>`}
  const run=S.payrollRun["2026-10"];
  return seg+`<div class="kpis"><div class="kpi"><small>October gross</small><b>${f3(payroll()*1.1)}</b><em>basic + 10% allowances</em></div><div class="kpi"><small>Staff paid</small><b>${S.STAFF.length}</b></div><div class="kpi"><small>Status</small><b style="font-size:18px">${run?'<span class="st ok" style="font-size:14px">Paid 28 Oct</span>':'<span class="st w" style="font-size:14px">Ready to run</span>'}</b></div></div>
   <div class="card"><h3>October 2026 payroll<span class="x">${run?"":`<button class="btn sm ok" onclick="S.payrollRun['2026-10']=true;toast('Payroll run · ${S.STAFF.length} payslips sent by email');go('expenses',{tab:'pay'})">Run payroll</button>`}</span></h3><div class="tbl"><table><thead><tr><th>Staff</th><th>Role</th><th class="r">Basic</th><th class="r">Allowances</th><th class="r">Deductions</th><th class="r">Net</th><th></th></tr></thead><tbody>${S.STAFF.map(s=>{const al=s.salary*.1,de=s.visa?0:s.salary*.07;return `<tr><td><b style="font-weight:600">${s.name}</b></td><td>${s.role}</td><td class="r num">${f3(s.salary)}</td><td class="r num">${f3(al)}</td><td class="r num">${de?f3(de):"—"}</td><td class="r num"><b>${f3(s.salary+al-de)}</b></td><td><button class="btn sm light" onclick="payslip('${s.id}')">Payslip</button></td></tr>`}).join("")}</tbody></table></div><div class="hint" style="margin-top:8px">Deductions shown for Omani staff (social insurance, illustrative 7%).</div></div>`};
function payslip(id){const s=ST(id),al=s.salary*.1,de=s.visa?0:s.salary*.07;modal(`<div class="printable doc">${docHead("PAYSLIP","October 2026")}<table><tbody><tr><td>Employee</td><td class="r"><b>${s.name}</b></td></tr><tr><td>Role</td><td class="r">${s.role}</td></tr><tr><td>Basic salary</td><td class="r num">${f3(s.salary)}</td></tr><tr><td>Housing & transport allowance</td><td class="r num">${f3(al)}</td></tr><tr><td>Social insurance</td><td class="r num">${de?"−"+f3(de):"—"}</td></tr><tr><td><b>Net pay</b></td><td class="r"><b>${f3(s.salary+al-de)} OMR</b></td></tr></tbody></table><div class="sig"><span>Accounts</span><span>Employee</span></div></div><div class="noprint" style="display:flex;gap:8px;margin-top:16px"><button class="btn" onclick="printDoc()">🖨 Print / PDF</button><button class="btn light" onclick="closeModal()">Close</button></div>`)}
function addExpense(){modal(mh("Add expense")+`<div class="f2"><div class="f"><label>Category</label><select id="xc"><option>Supplies</option><option>Food</option><option>Maintenance</option><option>Utilities</option><option>Marketing</option><option>Other</option></select></div><div class="f"><label>Amount (OMR)</label><input id="xa" type="number" step="0.001" value="45"></div></div><div class="f"><label>Description</label><input id="xd" value="Printer ink"></div><div class="f"><label>Receipt</label><input type="file"></div><button class="btn full" onclick="S.expenses.unshift([DEMO_TODAY,$('#xc').value,$('#xd').value,+$('#xa').value,'Card']);closeModal();toast('Expense saved');go('expenses')">Save expense</button>`)}

/* ---------- ASSESSMENT (exams dept) ---------- */
const MODST={entry:["w","Teacher entering marks"],submitted:["info","Submitted for moderation"],published:["ok","Published to parents"]};
V.assess=()=>{const bl=S.kids.map(k=>avg(kidMarks(k,"BL")));const support=S.kids.filter(k=>avg(kidMarks(k,"BL"))<58).length;
  return ph("","IPC developmental assessments: enter, moderate and publish to parents.")+`
  <div class="g g3" style="margin-bottom:14px">${S.windows.map(w=>`<div class="card" style="margin:0;border-top:4px solid ${w.status==="published"?"#1f9d68":w.status==="entry"?"#f7c51e":"#cfd5e2"}"><h3>${w.name}<span class="x"><span class="st ${w.status==="published"?"ok":w.status==="entry"?"gold":"mute"}">${w.status==="entry"?"In progress":w.status}</span></span></h3><div class="hint">${fd(w.from)} – ${fd(w.to)}</div></div>`).join("")}</div>
  <div class="kpis"><div class="kpi"><small>Mid-term marks entered</small><b>${entryPctAll()}%</b><em>deadline 29 Oct</em></div><div class="kpi"><small>Classes awaiting moderation</small><b>${Object.values(S.moderation).filter(x=>x==="submitted").length}</b></div><div class="kpi"><small>Baseline school average</small><b>${avg(bl).toFixed(1)}%</b></div><div class="kpi"><small>Children flagged for support</small><b>${support}</b><em class="w">avg below 58%</em></div></div>
  <div class="card"><h3>Mid-term review · progress by class</h3><div class="tbl"><table><thead><tr><th>Class</th><th>Teacher</th><th style="min-width:180px">Marks entered</th><th>Status</th><th></th></tr></thead><tbody>${S.CLASSES.map(c=>{const e=entryPct(c.id),m=S.moderation[c.id];return `<tr><td><b>${c.em} ${c.name}</b></td><td>${ST(c.teacher).name}</td><td><div style="display:flex;gap:8px;align-items:center"><div class="prog"><i style="width:${e}%;background:${e===100?"#1f9d68":"#f7c51e"}"></i></div><b class="num">${e}%</b></div></td><td><span class="st ${MODST[m][0]}">${MODST[m][1]}</span></td><td style="white-space:nowrap">${m==="submitted"?`<button class="btn sm navy" onclick="moderate('${c.id}')">Review & publish</button>`:m==="entry"?`<button class="btn sm light" onclick="logComm('App','${ST(c.teacher).name}','Reminder: mid-term marks due 29 Oct');toast('Reminder sent to ${ST(c.teacher).name}')">Remind</button>`:`<button class="btn sm light" onclick="go('reportcards',{cls:'${c.id}'})">Report cards</button>`}</td></tr>`}).join("")}</tbody></table></div></div>
  <div class="g g21"><div class="card"><h3>Baseline: average by learning area</h3>${chart("bar",{labels:AREAS.map(a=>a.split(" ")[0]),series:S.CLASSES.map(c=>({name:c.name,color:c.color,data:AREAS.map((a,i)=>Math.round(avg(classKids(c.id).map(k=>kidMarks(k,"BL")[i]))))})),max:100,unit:"%"},240)}<div class="legend">${S.CLASSES.map(c=>`<span><i style="background:${c.color}"></i>${c.name}</span>`).join("")}</div></div>
   <div class="card"><h3>Scale used</h3><div class="row"><span>${bandChip(90)}</span><span>85–100</span></div><div class="row"><span>${bandChip(75)}</span><span>70–84</span></div><div class="row"><span>${bandChip(60)}</span><span>50–69</span></div><div class="row"><span>${bandChip(40)}</span><span>below 50</span></div><div class="hint" style="margin-top:8px">Scores are teacher observations against IPC developmental goals, not tests.</div></div></div>`};
function moderate(cid){const ks=classKids(cid);modal(mh("Moderate · "+C(cid).name+" mid-term",ST(C(cid).teacher).name+" · "+ks.length+" children")+`<div class="tbl"><table><thead><tr><th>Child</th>${AREAS.map(a=>`<th class="r">${a.split(" ")[0].slice(0,5)}</th>`).join("")}<th>Overall</th></tr></thead><tbody>${ks.map(k=>{const m=kidMarks(k,"MT");return `<tr><td>${esc(k.name)}</td>${m.map(v=>`<td class="r num">${v??"–"}</td>`).join("")}<td>${bandChip(avg(m))}</td></tr>`}).join("")}</tbody></table></div><div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap"><button class="btn ok" onclick="publishCls('${cid}')">✓ Approve & publish to parents</button><button class="btn light" onclick="S.moderation['${cid}']='entry';closeModal();toast('Returned to teacher with comments');go('assess')">Return to teacher</button></div>`,"wide")}
function publishCls(cid){S.moderation[cid]="published";if(Object.values(S.moderation).every(x=>x==="published"))S.windows[1].status="published";logComm("App + WhatsApp",C(cid).name+" parents","Mid-term progress report published");closeModal();toast(C(cid).name+" reports published · parents notified");go(view==="reportcards"?"reportcards":"assess",param)}

V.gradebook=(p)=>{p=p||{};const cls=p.cls||"SF",w=p.w||"BL";const ks=classKids(cls);
  return `<div class="toolbar">${clsFilter("gc",cls,false)}<div class="seg"><button class="${w==="BL"?"on":""}" onclick="go('gradebook',{cls:'${cls}',w:'BL'})">Baseline</button><button class="${w==="MT"?"on":""}" onclick="go('gradebook',{cls:'${cls}',w:'MT'})">Mid-term</button></div><span class="sp"></span><button class="btn sm light" onclick="csv('gradebook-${cls}-${w}.csv',[['Student',...AREAS,'Average','Band']].concat(classKids('${cls}').map(k=>{const m=kidMarks(k,'${w}');const a=avg(m);return[k.name,...m,a==null?'':a.toFixed(1),a==null?'':band(a)[1]]})))">⬇ CSV</button></div>
  <div class="card"><div class="tbl"><table><thead><tr><th>Student</th>${AREAS.map((a,i)=>`<th class="r" title="${a}">${AREA_E[i]} ${a.split(" ")[0]}</th>`).join("")}<th class="r">Avg</th><th>Band</th></tr></thead><tbody>${ks.map(k=>{const m=kidMarks(k,w),a=avg(m);return `<tr class="click" onclick="kidProfile('${k.id}')"><td>${kidCell(k)}</td>${m.map(v=>`<td class="r num" style="${v==null?"color:#aab1c2":v<50?"color:#b33;font-weight:700":v>=85?"color:#1d55b8;font-weight:700":""}">${v??"–"}</td>`).join("")}<td class="r num"><b>${a==null?"–":a.toFixed(0)}</b></td><td>${bandChip(a)}</td></tr>`}).join("")}</tbody>
  <tfoot><tr><td><b>Class average</b></td>${AREAS.map((x,i)=>{const v=avg(ks.map(k=>kidMarks(k,w)[i]));return `<td class="r num"><b>${v==null?"–":v.toFixed(0)}</b></td>`}).join("")}<td></td><td></td></tr></tfoot></table></div></div>`};

V.reportcards=(p)=>{const cls=(p&&p.cls)||"TW";const m=S.moderation[cls];
  return `<div class="toolbar">${clsFilter("rc",cls,false)}<span class="sp"></span>${m==="submitted"?`<button class="btn sm ok" onclick="publishCls('${cls}')">Publish mid-term to parents</button>`:`<span class="st ${MODST[m][0]}">${MODST[m][1]}</span>`}</div>
  <div class="card"><div class="tbl"><table><thead><tr><th>Student</th><th>Baseline</th><th>Mid-term</th><th></th></tr></thead><tbody>${classKids(cls).map(k=>`<tr><td>${kidCell(k)}</td><td><span class="st ok">Published</span></td><td>${m==="published"?'<span class="st ok">Published</span>':kidMarks(k,"MT")[0]==null?'<span class="st mute">Awaiting marks</span>':'<span class="st w">Draft</span>'}</td><td style="white-space:nowrap"><button class="btn sm light" onclick="reportCard('${k.id}','BL')">Baseline</button> <button class="btn sm light" onclick="reportCard('${k.id}','MT')" ${kidMarks(k,"MT")[0]==null?"disabled":""}>Mid-term</button></td></tr>`).join("")}</tbody></table></div></div>`};
function reportCard(id,w){const k=K(id),win=S.windows.find(x=>x.id===w),m=kidMarks(k,w),bl=kidMarks(k,"BL");const draft=w==="MT"&&S.moderation[k.cls]!=="published";
  modal(`<div class="printable doc">${docHead("PROGRESS REPORT",win.name+" · 2026–27")}${draft?`<div class="test noprint">DRAFT: not yet published to parents</div>`:""}
  <div style="display:flex;gap:14px;align-items:center;margin-bottom:14px">${kidAv(k,"lg")}<div><b style="font-size:17px">${esc(k.name)}</b><br>${C(k.cls).name} · ${age(k)} · ID ${k.id}<br>Teacher: ${ST(C(k.cls).teacher).name}</div><div style="margin-inline-start:auto;text-align:end">Attendance<br><b style="font-size:20px">${Math.round(attRate(k)*100)}%</b></div></div>
  <table><thead><tr><th>Learning area (IPC)</th>${w==="MT"?'<th class="r">Baseline</th>':""}<th class="r">Score</th><th>Level</th></tr></thead><tbody>${AREAS.map((a,i)=>`<tr><td>${AREA_E[i]} ${a}</td>${w==="MT"?`<td class="r num">${bl[i]}</td>`:""}<td class="r num"><b>${m[i]??"–"}</b></td><td>${bandChip(m[i])}</td></tr>`).join("")}<tr><td><b>Overall</b></td>${w==="MT"?`<td class="r num">${avg(bl).toFixed(0)}</td>`:""}<td class="r num"><b>${avg(m)==null?"–":avg(m).toFixed(0)}</b></td><td>${bandChip(avg(m))}</td></tr></tbody></table>
  <div class="note" style="margin-top:14px"><b>Teacher's comment</b><br>${esc(S.comments[k.id]||"")}</div>
  <div class="sig"><span>Class teacher</span><span>Head of Assessment</span><span>Principal</span></div></div>
  <div class="noprint" style="display:flex;gap:8px;margin-top:16px"><button class="btn" onclick="printDoc()">🖨 Print / PDF</button><button class="btn light" onclick="closeModal()">Close</button></div>`,"wide")}

/* ---------- TEACHER ---------- */
V.teacherHome=()=>{const ks=classKids(me.cls),pr=ks.filter(k=>todayAtt(k)!=="A");const al=ks.filter(k=>k.allergy!=="None");const plan=S.lessons.find(l=>l.cls===me.cls);
  return ph("",`Good afternoon, Priya · ${C(me.cls).name} · ${C(me.cls).room} · Thursday 22 October`,`<button class="btn sm navy" onclick="go('daily')">📝 Update reports</button>`)+`
  <div class="kpis"><div class="kpi"><small>Present</small><b>${pr.length}<span> / ${ks.length}</span></b><em>${ks.length-pr.length} absent</em></div><div class="kpi"><small>Reports updated</small><b>${ks.filter(k=>S.daily[k.id].entries.length>2).length}<span> / ${pr.length}</span></b><em class="w">finish by 1:30</em></div><div class="kpi"><small>Mid-term marks</small><b>${entryPct(me.cls)}%</b><em class="w">due 29 Oct</em></div><div class="kpi"><small>Unread messages</small><b>${unread()}</b></div></div>
  ${al.length?`<div class="alert bad"><span>⚠️</span><span><b>Allergies in your class</b>${al.map(k=>k.first+": "+k.allergy).join(" · ")}</span></div>`:""}
  <div class="g g21"><div class="card"><h3>Today<span class="x"><button class="btn sm light" onclick="go('attendance')">Register</button></span></h3><div class="tbl"><table><thead><tr><th>Child</th><th>Status</th><th>Updates</th><th>Mood</th><th></th></tr></thead><tbody>${ks.map(k=>{const a=todayAtt(k),d=S.daily[k.id];return `<tr><td>${kidCell(k)}</td><td>${a==="A"?'<span class="st bad">Absent</span>':`<span class="st ok">In · ${S.checkin[k.id]}</span>`}</td><td>${d.entries.length}</td><td style="font-size:18px">${["😢","😐","🙂","😄"][d.mood]||"—"}</td><td>${a!=="A"?`<button class="btn sm" onclick="S.ui.sel='${k.id}';go('daily')">Update</button>`:""}</td></tr>`}).join("")}</tbody></table></div></div>
   <div class="stack"><div class="card"><h3>📚 This week: ${esc(plan.theme)}</h3>${plan.acts.map(a=>`<div class="row"><span>• ${esc(a)}</span></div>`).join("")}</div><div class="card"><h3>🗓️ Absence requests</h3>${S.leave.filter(l=>K(l.kid).cls===me.cls).map(leaveRow).join("")||'<div class="list-empty">None</div>'}</div><div class="card"><h3>📅 Coming up</h3>${upcoming(3).map(e=>`<div class="row"><span><b>${esc(e.title)}</b><small>${fdl(e.date)}</small></span></div>`).join("")}</div></div></div>`};

V.daily=()=>{
  if(me.role==="parent"){const k=curKid(),d=S.daily[k.id];return kidSwitch()+`<div class="g g2"><div class="card"><h3>📝 ${T("Daily report")}<span class="x">${fdl(DEMO_TODAY)}</span></h3>${d.entries.length?`<ul class="tl">${d.entries.map(e=>`<li><span class="t">${e[0]}</span><span class="e">${e[1]}</span><span>${esc(e[2])}</span></li>`).join("")}</ul>`:`<div class="list-empty">No updates yet today.</div>`}</div>
    <div class="stack"><div class="card"><h3>💛 ${T("Mood today")}</h3><div class="mood">${["😢","😐","🙂","😄"].map((m,i)=>`<span class="${i===d.mood?"on":""}">${m}</span>`).join("")}</div></div>${d.note?`<div class="card"><h3>👩‍🏫 ${T("Note from the teacher")}</h3><div class="note">${esc(d.note)}</div></div>`:""}</div></div>`}
  const ks=classKids(me.cls).filter(k=>todayAtt(k)!=="A");if(!ks.find(k=>k.id===S.ui.sel))S.ui.sel=ks[0].id;const k=K(S.ui.sel),d=S.daily[k.id];
  return `<div class="kidpick col">${ks.map(x=>`<button class="${x.id===k.id?"on":""}" onclick="S.ui.sel='${x.id}';go('daily')">${kidAv(x)}${x.first}${S.daily[x.id].entries.length>2?" ✓":""}</button>`).join("")}</div>
  <div class="g g2"><div class="card"><h3>⚡ Quick add · ${k.first}<span class="x">parent sees it instantly</span></h3><div class="quick">${[["🥣","Breakfast"],["🍛","Lunch"],["🍎","Snack"],["😴","Nap"],["🧷","Nappy"],["🚽","Toilet"],["🎨","Activity"],["💊","Medicine"]].map(q=>`<button onclick="quickAdd('${q[0]}','${q[1]}')"><span>${q[0]}</span>${q[1]}</button>`).join("")}</div>
   <h3 style="margin:16px 0 10px">💛 Mood</h3><div class="mood">${["😢","😐","🙂","😄"].map((m,i)=>`<button class="${i===d.mood?"on":""}" onclick="S.daily['${k.id}'].mood=${i};go('daily')">${m}</button>`).join("")}</div>
   <div class="f" style="margin-top:14px"><label>Note to parents</label><textarea id="tn" placeholder="How was ${k.first}'s day?">${esc(d.note)}</textarea></div><button class="btn full" onclick="S.daily['${k.id}'].note=$('#tn').value;logComm('App','${esc(k.mother)}','Daily note for ${k.first}');toast('Note sent to ${esc(k.mother)}');go('daily')">Send note</button></div>
  <div class="card"><h3>📝 Timeline<span class="x">what ${esc(k.mother.split(" ")[0])} sees</span></h3>${d.entries.length?`<ul class="tl">${d.entries.map(e=>`<li><span class="t">${e[0]}</span><span class="e">${e[1]}</span><span>${esc(e[2])}</span></li>`).join("")}</ul>`:'<div class="list-empty">Nothing yet</div>'}</div></div>`};
function quickAdd(e,l){const o={Breakfast:["ate all","ate some","ate little"],Lunch:["ate all","ate some","ate little"],Snack:["ate all","ate some","refused"],Nap:["30 min","1 hour","1.5 hours","no nap"],Nappy:["wet","dry","BM"],Toilet:["success","accident"],Activity:["Painting","Outdoor play","Story time","Music & movement","Blocks & puzzles"],Medicine:["given as per form"]}[l];
  modal(mh(e+" "+l+" · "+K(S.ui.sel).first,"Timestamped "+nowT())+`<div style="display:grid;gap:8px">${o.map(x=>`<button class="btn ghost" onclick="addRep('${e}','${l}','${x}')">${x}</button>`).join("")}</div>`)}
function addRep(e,l,o){const k=K(S.ui.sel);S.daily[k.id].entries.push([nowT(),e,l==="Activity"?o:l+" – "+o]);closeModal();toast(`Added · ${k.mother.split(" ")[0]} notified`);go("daily")}

V.marks=()=>{const ks=classKids(me.cls),m=S.moderation[me.cls];const locked=m!=="entry";
  return ph("",`${S.windows[1].name} · ${C(me.cls).name} · 0–100 per learning area · due 29 Oct`,locked?`<span class="st ${MODST[m][0]}">${MODST[m][1]}</span>`:`<button class="btn sm light" onclick="save();toast('Draft saved')">Save draft</button><button class="btn sm navy" onclick="submitMarks()">Submit for moderation</button>`)+`
  <div class="card"><div class="tbl"><table><thead><tr><th>Child</th>${AREAS.map((a,i)=>`<th style="text-align:center" title="${a}">${AREA_E[i]}<br>${a.split(" ")[0].slice(0,6)}</th>`).join("")}<th>Overall</th><th></th></tr></thead><tbody>${ks.map(k=>{const mk=kidMarks(k,"MT"),a=avg(mk);return `<tr><td>${kidCell(k,"Baseline "+Math.round(avg(kidMarks(k,"BL"))))}</td>${mk.map((v,i)=>`<td style="text-align:center"><input class="grid-input" inputmode="numeric" ${locked?"disabled":""} value="${v??""}" onchange="setMark('${k.id}',${i},this)"></td>`).join("")}<td id="ov-${k.id}">${bandChip(a)}</td><td><button class="btn sm light" onclick="editComment('${k.id}')">💬</button></td></tr>`}).join("")}</tbody></table></div><div class="hint" style="margin-top:8px">${entryPct(me.cls)}% entered · changes save automatically</div></div>`};
function setMark(id,i,el){let v=el.value.trim();if(v===""){S.marks.MT[id][i]=null}else{v=+v;if(isNaN(v)||v<0||v>100){el.classList.add("bad");toast("Enter 0–100");return}S.marks.MT[id][i]=Math.round(v)}el.classList.remove("bad");$("#ov-"+id).innerHTML=bandChip(avg(S.marks.MT[id]));save()}
function submitMarks(){const miss=classKids(me.cls).filter(k=>kidMarks(k,"MT").some(v=>v==null));if(miss.length){toast(`${miss.length} children still have missing marks: ${miss.slice(0,3).map(k=>k.first).join(", ")}…`);return}S.moderation[me.cls]="submitted";logComm("App","Ms. Lina Haddad",C(me.cls).name+" mid-term submitted");toast("Submitted to Head of Assessment");go("marks")}
function fillDemo(){classKids(me.cls).forEach(k=>{S.marks.MT[k.id]=S.marks.MT[k.id].map((v,i)=>v??Math.min(99,S.marks.BL[k.id][i]+Math.round(Math.random()*9)))});save();go("marks")}
function editComment(id){const k=K(id);modal(mh("Comment · "+esc(k.name))+`<div class="f"><textarea id="cm" style="min-height:120px">${esc(S.comments[id])}</textarea></div><button class="btn full" onclick="S.comments['${id}']=$('#cm').value;closeModal();toast('Comment saved')">Save</button>`)}

V.homework=()=>{const parent=me.role==="parent";const clss=parent?parentKids().map(k=>k.cls):[me.cls];const list=S.homework.filter(h=>clss.includes(h.cls));
  return ph("",parent?"Simple activities to enjoy together at home":"Set home activities for parents to do with their child",parent?"":`<button class="btn sm navy" onclick="setHw()">+ Set activity</button>`)+`<div class="g g2">${list.map(h=>{const i=S.homework.indexOf(h),ks=classKids(h.cls);const k=parent?parentKids().find(x=>x.cls===h.cls):null;const done=k&&h.done.includes(k.id);
   return `<div class="card"><h3>🏡 ${esc(h.title)}<span class="x">${fd(h.date)}</span></h3><p style="font-size:13.5px;margin-bottom:10px">${esc(h.detail)}</p>${parent?(done?'<span class="st ok">✓ Done · photo shared</span>':`<button class="btn sm" onclick="S.homework[${i}].done.push('${k.id}');toast('Shared with ${C(h.cls).name} teacher 📸');go('homework')">📸 Share a photo & mark done</button>`):`<div style="display:flex;gap:8px;align-items:center"><div class="prog"><i style="width:${pct(h.done.length,ks.length)}%;background:#3fb37f"></i></div><span class="hint">${h.done.length}/${ks.length} families</span></div>`}</div>`}).join("")}</div>`};
function setHw(){modal(mh("Set home activity")+`<div class="f"><label>Title</label><input id="hwt" value="Count 5 fruits"></div><div class="f"><label>Instructions</label><textarea id="hwd">Count fruits together at home and draw them.</textarea></div><button class="btn full" onclick="S.homework.unshift({cls:me.cls,date:DEMO_TODAY,title:$('#hwt').value,detail:$('#hwd').value,done:[]});logComm('App',C(me.cls).name+' parents','New home activity');closeModal();toast('Sent to parents');go('homework')">Send to parents</button>`)}

V.photos=()=>{const PC=["#ffe27a","#c9f0f7","#ffd6d6","#d9f2e3","#e6defc","#ffe9c7"];
  if(me.role==="parent"){const ids=parentKids().map(k=>k.id),cl=parentKids().map(k=>k.cls);const mine=S.photos.filter(p=>ids.includes(p[1])||(p[1]==null&&cl.includes(p[2])));
    return `<div class="card"><h3>📷 ${T("Photos")}<span class="x">${mine.length} this week</span></h3><div class="gal">${mine.map((p,i)=>`<div class="ph" style="background:${PC[i%6]}">${p[0]}<small>${p[1]?K(p[1]).first:C(p[2]).name}</small></div>`).join("")}</div></div><div class="alert info"><span>🔒</span><span>Only you see photos tagged with your child. Class photos are shared with that class's parents only, and only with photo consent.</span></div>`}
  const mine=S.photos.filter(p=>p[2]===me.cls);
  return `<div class="card"><h3>📷 Share photos</h3><div class="f2"><div class="f"><label>Tag</label><select id="pt"><option value="">Whole class (consent only)</option>${classKids(me.cls).map(k=>`<option value="${k.id}">${esc(k.name)}${k.consent?"":" ⚠️ no consent"}</option>`).join("")}</select></div><div class="f"><label>Photo</label><button class="btn full light" onclick="upPhoto()">📸 Take / upload</button></div></div></div>
  <div class="card"><h3>Shared this week<span class="x">${mine.length}</span></h3><div class="gal">${mine.map((p,i)=>`<div class="ph" style="background:${PC[i%6]}">${p[0]}<small>${p[1]?K(p[1]).first:"Class"}</small></div>`).join("")}</div></div>`};
function upPhoto(){const t=$("#pt").value||null;if(t&&!K(t).consent){toast("No photo consent on file for "+K(t).first);return}const em=["🫧","🏗️","🎈","🐢","🧁","🚂","🌈","🪁"];S.photos.unshift([em[S.photos.length%em.length],t,me.cls]);toast(t?"Shared with "+K(t).mother:"Shared with "+C(me.cls).name+" parents");go("photos")}

/* ---------- MESSAGES ---------- */
V.messages=(p)=>{const mine=S.messages.filter(m=>me.role==="teacher"?m.with===me.staff:me.role==="parent"?parentKids().some(k=>k.id===m.kid):true);
  const cur=mine.find(m=>m.id===(p&&p.id))||(innerWidth>900?mine[0]:null);if(cur&&me.role==="parent")cur.read=true;const side=me.role==="parent"?"parent":"staff";
  return `${me.role==="parent"?`<div class="toolbar"><span class="sp"></span><button class="btn sm navy" onclick="newThread()">+ New message</button></div>`:me.role==="admin"?`<div class="alert info"><span>👁️</span><span>Office view: all parent–teacher conversations, for safeguarding.</span></div>`:""}
  <div class="card thread ${cur&&innerWidth<=900?"open":""}"><div class="tl2">${mine.map(m=>{const k=K(m.kid),last=m.msgs[m.msgs.length-1];return `<button class="ti ${cur&&cur.id===m.id?"on":""}" onclick="go('messages',{id:'${m.id}'})">${me.role==="parent"?`<span class="av sm n">${ini(ST(m.with).name)}</span>`:kidAv(k)}<span style="min-width:0"><b>${me.role==="parent"?ST(m.with).name:esc(k.mother)} ${last.from!==side&&!m.read?"🟡":""}</b><small>${esc(k.first)} · ${esc(last.x)}</small></span></button>`}).join("")}</div>
  ${cur?`<div class="conv"><div class="ch">${innerWidth<=900?`<button class="btn sm light" onclick="go('messages',{id:'_'})">‹</button>`:""}<span class="mini"><span class="av sm n">${ini(me.role==="parent"?ST(cur.with).name:K(cur.kid).mother)}</span><span><b>${me.role==="parent"?ST(cur.with).name:esc(K(cur.kid).mother)}</b><small>${esc(cur.subject)} · re ${K(cur.kid).first}</small></span></span></div>
   <div class="msgs" id="msgs">${cur.msgs.map(x=>`<div class="bub ${x.from===side?"me":""}">${esc(x.x)}<small>${x.t.slice(11)} · ${fd(x.t)}</small></div>`).join("")}</div>
   ${me.role==="admin"?"":`<form onsubmit="sendMsg(event,'${cur.id}')"><input id="mi" placeholder="Write a message…" autocomplete="off"><button class="btn">Send</button></form>`}</div>`:`<div class="list-empty" style="padding:40px">Select a conversation</div>`}</div>`};
function sendMsg(e,id){e.preventDefault();const v=$("#mi").value.trim();if(!v)return;const m=S.messages.find(x=>x.id===id),side=me.role==="parent"?"parent":"staff";m.msgs.push({from:side,t:DEMO_TODAY+" "+nowT(),x:v});go("messages",{id});
  setTimeout(()=>{if(view!=="messages")return;m.msgs.push({from:side==="parent"?"staff":"parent",t:DEMO_TODAY+" "+nowT(),x:side==="parent"?"Thanks for letting me know, noted 😊":"Thank you! 🙏"});if(side==="parent")m.read=false;go("messages",{id})},2200)}
function newThread(){modal(mh("New message")+`<div class="f"><label>About</label><select id="nk">${parentKids().map(k=>`<option value="${k.id}">${k.first} · ${C(k.cls).name}</option>`).join("")}</select></div><div class="f"><label>Subject</label><input id="ns" value="Question"></div><div class="f"><label>Message</label><textarea id="nm2"></textarea></div><button class="btn full" onclick="const k=K($('#nk').value);const id='M'+Date.now();S.messages.unshift({id,kid:k.id,with:C(k.cls).teacher,subject:$('#ns').value,msgs:[{from:'parent',t:DEMO_TODAY+' '+nowT(),x:$('#nm2').value||'Hello!'}]});closeModal();go('messages',{id})">Send to ${"teacher"}</button>`)}

/* ---------- PARENT ---------- */
function kidSwitch(){const ks=parentKids();return `<div class="kidpick">${ks.map(k=>`<button class="${k.id===curKid().id?"on":""}" onclick="S.ui.kid='${k.id}';go(view,param)">${kidAv(k)}${lang==="ar"?{Layla:"ليلى",Hamad:"حمد"}[k.first]:k.first} · ${C(k.cls).name}</button>`).join("")}</div>`}
function kidHero(k){const a=todayAtt(k);return `<div class="hero"><div class="av lg" style="background:${C(k.cls).bg}">${ini(k.name)}</div><div style="flex:1;min-width:160px"><b style="font-size:18px">${lang==="ar"?({Layla:"ليلى الحارثي",Hamad:"حمد الحارثي"}[k.first]):esc(k.name)}</b><br><small>${C(k.cls).em} ${C(k.cls).name} · ${age(k)} · ${ST(C(k.cls).teacher).name}</small></div>${a==="A"?`<span class="pill abs">${T("Absent today")}</span>`:`<span class="pill">● ${T("Checked in")} ${S.checkin[k.id]}</span>`}</div>`}
V.parentHome=()=>{const k=curKid(),d=S.daily[k.id];const due=parentKids().flatMap(kidInvoices).filter(i=>i.status!=="paid");const pub=S.moderation[k.cls]==="published";const m=kidMarks(k,pub?"MT":"BL");const ev=upcoming(10).filter(e=>e.cls==="All"||e.cls===k.cls)[0];
  return kidSwitch()+kidHero(k)+`<div class="kpis">
   <div class="kpi" onclick="go('pAttendance')" style="cursor:pointer"><small>✅ ${T("Attendance this term")}</small><b>${Math.round(attRate(k)*100)}%</b><em>${[...S.att[k.id]].filter(c=>c==="A").length} days absent</em></div>
   <div class="kpi" onclick="go('progress')" style="cursor:pointer"><small>📊 ${T("Latest progress")}</small><b>${Math.round(avg(m))}%</b><em>${band(avg(m))[1]} · ${pub?"Mid-term":"Baseline"}</em></div>
   <div class="kpi" onclick="go('fees')" style="cursor:pointer"><small>💳 ${T("Fees due")}</small><b>${f3(due.reduce((s,i)=>s+i.amount,0))}</b><em class="${due.length?"w":"up"}">${due.length?"due 1 Nov · tap to pay":"all paid ✓"}</em></div>
   <div class="kpi" onclick="go('events')" style="cursor:pointer"><small>📅 ${T("Next event")}</small><b style="font-size:16px;line-height:1.3">${esc(ev.title)}</b><em>${fdl(ev.date)}</em></div></div>
  <div class="g g2"><div class="card"><h3>📝 ${T("Today")}<span class="x"><button class="btn sm light" onclick="go('daily')">Full report</button></span></h3>${d.entries.length?`<ul class="tl">${d.entries.slice(-5).map(e=>`<li><span class="t">${e[0]}</span><span class="e">${e[1]}</span><span>${esc(e[2])}</span></li>`).join("")}</ul>`:'<div class="list-empty">No updates yet</div>'}${d.note?`<div class="note" style="margin-top:10px">${esc(d.note)}</div>`:""}</div>
   <div class="stack"><div class="card"><h3>⚡ Quick actions</h3><div class="quick"><button onclick="reportAbsence()"><span>🤒</span>Absence</button><button onclick="go('messages')"><span>💬</span>Message</button><button onclick="go('fees')"><span>💳</span>Pay fees</button><button onclick="go('pickup')"><span>🚸</span>Pick-up</button></div></div>
   <div class="card"><h3>📣 ${T("Announcements")}</h3>${S.news.filter(n=>n.to==="All"||n.to===k.cls).slice(0,3).map(n=>`<div class="row"><span><b>${esc(n.title)}</b><small>${fd(n.date)}</small></span></div>`).join("")}</div></div></div>`};
function calMonth(k,month){const idx={};S.days.forEach((d,i)=>idx[d]=i);const d0=new Date(month+"-01T00:00:00"),n=new Date(d0.getFullYear(),d0.getMonth()+1,0).getDate();
  let h=["Sun","Mon","Tue","Wed","Thu"].map(x=>`<div class="h">${x}</div>`).join("");let first=true;
  for(let d=1;d<=n;d++){const ds=month+"-"+String(d).padStart(2,"0"),wd=new Date(ds).getDay();if(wd>4)continue;if(first){for(let i=0;i<wd;i++)h+="<div></div>";first=false}
    const i=idx[ds],s=i==null?(ds>DEMO_TODAY?"":"H"):S.att[k.id][i];const ev=S.events.some(e=>e.date===ds&&(e.cls==="All"||e.cls===k.cls));
    h+=`<div class="d ${s} ${ds===DEMO_TODAY?"T":""} ${ev?"E":""}" data-tip="${fdl(ds)}${s==="P"?" · Present":s==="L"?" · Late":s==="A"?" · Absent":""}">${d}</div>`}
  return `<div class="cal" style="grid-template-columns:repeat(5,1fr)">${h}</div>`}
V.pAttendance=()=>{const k=curKid(),s=S.att[k.id];
  return kidSwitch()+`<div class="kpis"><div class="kpi"><small>${T("Attendance this term")}</small><b>${Math.round(attRate(k)*100)}%</b><em>class avg ${Math.round(avg(classKids(k.cls).map(x=>attRate(x)))*100)}%</em></div><div class="kpi"><small>Present</small><b>${[...s].filter(c=>c==="P").length}</b></div><div class="kpi"><small>Late</small><b>${[...s].filter(c=>c==="L").length}</b></div><div class="kpi"><small>Absent</small><b>${[...s].filter(c=>c==="A").length}</b></div></div>
  <div class="g g2"><div class="card"><h3>September</h3>${calMonth(k,"2026-09")}</div><div class="card"><h3>October</h3>${calMonth(k,"2026-10")}</div></div>
  <div class="legend" style="margin:0 0 14px"><span><i style="background:#1f9d6855"></i>Present</span><span><i style="background:#d9850055"></i>Late</span><span><i style="background:#d6454555"></i>Absent</span><span><i style="background:#f7c51e"></i>Event</span></div>
  <div class="card"><h3>🤒 ${T("Report an absence")}<span class="x"><button class="btn sm navy" onclick="reportAbsence()">+ Report</button></span></h3>${S.leave.filter(l=>parentKids().some(x=>x.id===l.kid)).map(leaveRow).join("")||'<div class="hint">No absence requests yet. Let the teacher know in advance if your child will be away.</div>'}</div>`};
function reportAbsence(){modal(mh(T("Report an absence"),"Goes straight to the teacher and office")+`<div class="f"><label>Child</label><select id="ak">${parentKids().map(k=>`<option value="${k.id}" ${k.id===curKid().id?"selected":""}>${k.first}</option>`).join("")}</select></div><div class="f2"><div class="f"><label>From</label><input type="date" id="af" value="2026-10-25"></div><div class="f"><label>To</label><input type="date" id="at" value="2026-10-25"></div></div><div class="f"><label>Reason</label><select id="ar"><option>Sick</option><option>Doctor's appointment</option><option>Family travel</option><option>Other</option></select></div><button class="btn full" onclick="S.leave.unshift({id:'LV'+Date.now(),kid:$('#ak').value,from:$('#af').value,to:$('#at').value,reason:$('#ar').value,status:'pending',at:DEMO_TODAY+' '+nowT()});closeModal();toast('Sent to teacher & office');go(view)">Send</button>`)}
V.progress=(p)=>{const k=curKid(),pub=S.moderation[k.cls]==="published";const w=(p&&p.w)||(pub?"MT":"BL");const m=kidMarks(k,w),bl=kidMarks(k,"BL");
  return kidSwitch()+`<div class="toolbar"><div class="seg"><button class="${w==="BL"?"on":""}" onclick="go('progress',{w:'BL'})">Baseline · Sep</button><button class="${w==="MT"?"on":""}" onclick="go('progress',{w:'MT'})">Mid-term · Oct</button></div><span class="sp"></span>${w==="BL"||pub?`<button class="btn sm navy" onclick="reportCard('${k.id}','${w}')">📄 ${T("Report card")}</button>`:""}</div>
  ${w==="MT"&&!pub?`<div class="card" style="text-align:center;padding:36px"><div style="font-size:44px">⏳</div><h3 style="justify-content:center;margin:8px 0 4px">Mid-term report coming soon</h3><div class="hint">Teachers are completing assessments. You'll get a notification when ${k.first}'s report is published (after 29 Oct).</div></div>`:`
  <div class="g g21"><div class="card"><h3>📊 ${T("Learning areas")}</h3>${chart("bar",{labels:AREAS.map(a=>a.split(" ")[0]),series:w==="MT"?[{name:"Baseline",color:"#cfd5e2",data:bl},{name:"Mid-term",color:"#f7c51e",data:m}]:[{name:"Baseline",color:"#14213d",data:m}],max:100,unit:"%"},240)}${w==="MT"?'<div class="legend"><span><i style="background:#cfd5e2"></i>Baseline</span><span><i style="background:#f7c51e"></i>Mid-term</span></div>':""}</div>
   <div class="card"><h3>Overall</h3><div style="text-align:center;padding:10px 0"><div style="font-family:'Baloo 2';font-size:52px;color:var(--navy);line-height:1">${Math.round(avg(m))}%</div>${bandChip(avg(m))}${w==="MT"?`<div class="hint" style="margin-top:8px">+${(avg(m)-avg(bl)).toFixed(1)} points since September 🌟</div>`:""}</div></div></div>
  <div class="card" style="margin-top:14px">${AREAS.map((a,i)=>`<div class="row"><span>${AREA_E[i]} <b>${a}</b></span><span style="display:flex;gap:8px;align-items:center"><b class="num">${m[i]}%</b>${bandChip(m[i])}</span></div>`).join("")}</div>
  <div class="card"><h3>👩‍🏫 ${T("Teacher's comment")}</h3><div class="note">${esc(S.comments[k.id])}</div></div>`}`};
V.fees=()=>{const ks=parentKids();const inv=ks.flatMap(kidInvoices).sort((a,b)=>b.month.localeCompare(a.month));const due=inv.filter(i=>i.status!=="paid");const tot=due.reduce((s,i)=>s+i.amount,0);
  return `<div class="hero" style="display:block">${due.length?`<small>Total due · ${due.map(i=>K(i.kid).first+" "+monthName(i.month)).join(" + ")}</small><div class="amt">${f3(tot)} OMR</div><div style="font-size:12px;opacity:.85;margin-bottom:14px">Due 1 November 2026${ks.some(k=>k.discount)?" · sibling discount applied":""}</div><button class="btn" style="max-width:320px;width:100%" onclick="payModal()">💳 ${T("Pay now by card")}</button>`:`<small>Fees</small><div class="amt">0.000 OMR</div><div>✅ ${T("All paid — thank you!")}</div>`}</div>
  <div class="card"><h3>🧾 Invoices & ${T("Payment history")}</h3>${inv.map(i=>{const r=S.payments.find(p=>p.inv===i.no);return `<div class="row"><span><b style="font-weight:600">${esc(i.item)}</b><small>${K(i.kid).first} · ${i.no}${r?" · "+r.method+(r.card?" •••• "+r.card:""):""}</small></span><span style="text-align:end;display:flex;gap:8px;align-items:center"><span><b class="num">${f3(i.amount)}</b><br>${invStatus(i)}</span>${r?`<button class="btn sm light" onclick="receipt('${r.no}')">Receipt</button>`:`<button class="btn sm light" onclick="voucher('${i.no}')">Invoice</button>`}</span></div>`}).join("")}</div>`};
function payModal(){const due=parentKids().flatMap(kidInvoices).filter(i=>i.status!=="paid");
  modal(mh("Pay school fees","TwinkleStar International ChildCare")+`<div class="test">DEMO MODE: use test card 4242 4242 4242 4242. Nothing is charged.</div>${due.map(i=>`<label class="sum" style="cursor:pointer"><span><input type="checkbox" class="pi" value="${i.no}" checked onchange="updTot()"> ${esc(i.item)} · ${K(i.kid).first}</span><span class="num">${f3(i.amount)}</span></label>`).join("")}<div class="sum tot"><span>Total</span><span id="ptot">${f3(due.reduce((s,i)=>s+i.amount,0))} OMR</span></div><div style="height:12px"></div>
  <div class="f"><label>Name on card</label><input id="cn" value="Fatma Al-Harthy" autocomplete="off"></div><div class="f"><label>Card number</label><input id="cc" placeholder="4242 4242 4242 4242" inputmode="numeric" maxlength="19" autocomplete="off"></div><div class="f2"><div class="f"><label>Expiry</label><input id="ce" placeholder="MM/YY" maxlength="5" inputmode="numeric" autocomplete="off"></div><div class="f"><label>CVV</label><input id="cv" placeholder="123" maxlength="4" inputmode="numeric" autocomplete="off"></div></div>
  <button class="btn full" id="payBtn" onclick="doPay()">Pay securely</button><div class="secure">🔒 In the live system, card details go directly to a licensed Omani payment gateway with 3-D Secure. TwinkleStar never sees or stores them.</div>`);
  const cc=$("#cc");cc.oninput=()=>{cc.value=cc.value.replace(/\D/g,"").slice(0,16).replace(/(.{4})/g,"$1 ").trim()};const ce=$("#ce");ce.oninput=()=>{let v=ce.value.replace(/\D/g,"").slice(0,4);ce.value=v.length>2?v.slice(0,2)+"/"+v.slice(2):v}}
function updTot(){const t=[...document.querySelectorAll(".pi:checked")].reduce((s,c)=>s+S.invoices.find(i=>i.no===c.value).amount,0);$("#ptot").textContent=f3(t)+" OMR";$("#payBtn").disabled=!t}
function doPay(){const num=$("#cc").value.replace(/\s/g,"");if(num.length<16){toast("Enter the 16-digit test card number");return}const sel=[...document.querySelectorAll(".pi:checked")].map(c=>c.value);if(!sel.length)return;
  const box=document.querySelector(".modal");box.innerHTML=`<div class="done"><div class="spin"></div><p>Contacting payment gateway…<br><small>3-D Secure verification</small></p></div>`;
  setTimeout(()=>{let tot=0,rs=[];sel.forEach(no=>{const i=S.invoices.find(x=>x.no===no);i.status="paid";tot+=i.amount;const r={no:"RCP-"+(6000+S.payments.length),inv:no,kid:i.kid,amount:i.amount,method:"Card",card:num.slice(-4),date:DEMO_TODAY,by:"Parent portal"};S.payments.unshift(r);rs.push(r.no)});
    logComm("WhatsApp + Email","Fatma Al-Harthy","Payment received "+f3(tot)+" OMR · "+rs.join(", "));save();
    box.innerHTML=`<div class="done"><div class="big">✅</div><h3>Payment successful</h3><p>${f3(tot)} OMR paid by card •••• ${num.slice(-4)}<br>Receipt ${rs.join(", ")} sent by email & WhatsApp.</p><div style="height:14px"></div><button class="btn full" onclick="receipt('${rs[0]}')">View receipt</button><button class="btn full light" style="margin-top:8px" onclick="closeModal()">Done</button></div>`;go("fees")},1700)}
V.pickup=()=>{const k=curKid();return kidSwitch()+`<div class="g g2"><div class="card" style="text-align:center"><h3 style="justify-content:center">🎫 ${T("Pick-up pass")} · ${k.first}</h3>${qrSvg(k.id+"-pass")}<div class="hint" style="margin-top:10px">Show this at the entrance for check-in & pick-up.<br>Refreshes daily · valid ${fdl(DEMO_TODAY)}</div><button class="btn sm light" style="margin-top:12px" onclick="modal(mh('One-time pick-up code','Share with someone picking up today only')+'<div style=&quot;font-family:Baloo 2;font-size:44px;text-align:center;letter-spacing:8px;color:#14213d&quot;>${(k.id.slice(1)*7919%9000+1000)}</div><div class=&quot;hint&quot; style=&quot;text-align:center&quot;>Valid until 14:00 today. ID will be checked.</div>')">Create one-time code</button></div>
  <div class="card"><h3>🚸 ${T("Approved pick-up people")}<span class="x"><button class="btn sm navy" onclick="addPickup()">+ Add</button></span></h3>${k.pickup.map(p=>`<div class="row"><span class="mini"><span class="av sm n">${ini(p[0])}</span><span><b>${esc(p[0])}</b><small>${p[1]}</small></span></span><span class="st ${p[2]==="pending"?"w":"ok"}">${p[2]==="pending"?"Awaiting office":"Approved"}</span></div>`).join("")}<div class="hint" style="margin-top:10px">Only these people can collect ${k.first}. ID is checked at the door.</div></div></div>`};
function addPickup(){modal(mh("Add pick-up person","The office verifies ID before approval")+`<div class="f"><label>Full name</label><input id="pn" value="Maryam Al-Harthy"></div><div class="f2"><div class="f"><label>Relationship</label><input id="pr2" value="Grandmother"></div><div class="f"><label>Civil ID / passport no.</label><input id="pi2" value="12345678"></div></div><div class="f"><label>Photo of ID</label><input type="file"></div><button class="btn full" onclick="curKid().pickup.push([$('#pn').value,$('#pr2').value,'pending']);closeModal();toast('Sent to the office for approval');go('pickup')">Submit</button>`)}
